"""Application-owned SQLAlchemy declarations; importing this module performs no IO."""

from sqlalchemy import MetaData, Table, Column, String, Integer, ForeignKey, CheckConstraint

metadata = MetaData()
users = Table("users", metadata, Column("id", String, primary_key=True), Column("name", String, nullable=False), Column("password_hash", String, nullable=False))
files = Table("files", metadata, Column("id", String, primary_key=True), Column("owner_id", String, ForeignKey("users.id"), nullable=False), Column("filename", String, nullable=False), Column("size", Integer, nullable=False), Column("created_at", String, nullable=False), CheckConstraint("size >= 0", name="file_size_nonnegative"))
shares = Table("shares", metadata, Column("id", String, primary_key=True), Column("file_id", String, ForeignKey("files.id"), nullable=False), Column("owner_id", String, ForeignKey("users.id"), nullable=False), Column("recipient_id", String, ForeignKey("users.id"), nullable=False), Column("reviewer_id", String, ForeignKey("users.id"), nullable=False), Column("state", String, nullable=False), Column("revision", Integer, nullable=False), Column("created_at", String, nullable=False), CheckConstraint("state IN ('pending','approved','rejected','cancelled','revoked')", name="share_state_valid"), CheckConstraint("owner_id != recipient_id", name="different_recipient"), CheckConstraint("revision >= 1", name="share_revision_positive"))
notifications = Table("notifications", metadata, Column("id", String, primary_key=True), Column("user_id", String, ForeignKey("users.id"), nullable=False), Column("share_id", String, ForeignKey("shares.id"), nullable=False), Column("kind", String, nullable=False), Column("state", String, nullable=False), Column("filename", String, nullable=False), Column("is_read", Integer, nullable=False, server_default="0"), Column("created_at", String, nullable=False))
journal = Table("journal", metadata, Column("id", String, primary_key=True), Column("share_id", String, ForeignKey("shares.id"), nullable=False), Column("revision", Integer, nullable=False), Column("event", String, nullable=False), Column("before_state", String, nullable=False), Column("after_state", String, nullable=False), Column("guards", String, nullable=False), Column("created_at", String, nullable=False))
